using System.ComponentModel;
using System.Globalization;

namespace SatisfactoryPlanner;

/// <summary>
/// UI text translations. Game names (items, buildings, recipes, unlock text) come from the localized
/// wiki data instead — see GameData.Load. XAML binds with {Binding [key], Source={x:Static local:Loc.Instance}}
/// so switching language updates the window live.
/// </summary>
public class Loc : INotifyPropertyChanged
{
    public static Loc Instance { get; } = new();
    /// <summary>
    /// Languages offered: English, every language the local game install ships, plus the wiki's de/fr.
    /// Game names switch for all of them; the app's own UI text is translated for de, fr and zh-Hans (English otherwise).
    /// </summary>
    public static List<(string code, string name)> Languages { get; } = BuildLanguages();

    static List<(string code, string name)> BuildLanguages()
    {
        var codes = new List<string> { "en" };
        codes.AddRange(GameLocale.Languages());
        codes.AddRange(GameData.WikiLanguages.Select(w => w.lang));
        return codes.Distinct().Select(c => (c, c == "en" ? "English" : Native(c)))
            .OrderBy(l => l.c == "en" ? 0 : 1).ThenBy(l => l.Item2, StringComparer.CurrentCulture).ToList();
    }

    static string Native(string code)
    {
        try { var n = CultureInfo.GetCultureInfo(code).NativeName; return char.ToUpper(n[0]) + n[1..]; }
        catch (CultureNotFoundException) { return code; }
    }

    string _lang = "en";
    public string Language
    {
        get => _lang;
        set
        {
            _lang = Languages.Any(l => l.code == value) ? value : "en";
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        }
    }

    public string this[string key]
    {
        get
        {
            if (_lang.StartsWith("zh-Hans") && Zh.TryGetValue(key, out var zh)) return zh;
            if (!Table.TryGetValue(key, out var r)) return key;
            return (_lang == "de" ? r.de : _lang == "fr" ? r.fr : r.en) ?? r.en;
        }
    }

    public static string T(string key, params object[] args) =>
        args.Length == 0 ? Instance[key] : string.Format(CultureInfo.CurrentCulture, Instance[key], args);

    /// <summary>Default to the OS language when we have it (exact match first, e.g. zh-Hans, then the two-letter code).</summary>
    public static string DefaultLanguage()
    {
        var ui = CultureInfo.CurrentUICulture;
        foreach (var c in new[] { ui.Name, ui.Parent.Name, ui.TwoLetterISOLanguageName })
            if (Languages.Any(l => l.code.Equals(c, StringComparison.OrdinalIgnoreCase)))
                return Languages.First(l => l.code.Equals(c, StringComparison.OrdinalIgnoreCase)).code;
        return "en";
    }

    public event PropertyChangedEventHandler? PropertyChanged;

