        ["chk.twoSplitters"] = ("Allow 2 splitters in a row (default: 1)", "2 Splitter hintereinander erlauben (Standard: 1)", "Autoriser 2 répartiteurs à la suite (par défaut : 1)"),
        ["kind.logistics"] = ("Belt / pipe part", "Band-/Rohrteil", "Pièce convoyeur / tuyau"),
        ["node.sink"] = ("Sink / storage", "Senke / Lager", "Broyeur / stockage"),
        ["split.smart"] = ("Smart splitter: {0} on normal outputs, {1} on Overflow (only gets what the machines can't take)", "Intelligenter Splitter: {0} an normalen Ausgängen, {1} an Überlauf (bekommt nur, was die Maschinen nicht aufnehmen)", "Répartiteur intelligent : {0} sur les sorties normales, {1} en Débordement (ne reçoit que ce que les machines ne prennent pas)"),
        ["split.pipe"] = ("Pipe manifold with junctions (fluids share by demand)", "Rohr-Verteiler mit Verbindungsstücken (Flüssigkeiten teilen sich nach Bedarf)", "Collecteur de tuyaux avec jonctions (les fluides se répartissent selon la demande)"),
        ["chk.endSplitter"] = ("Splitter in front of the last machine too (for looks)", "Splitter auch vor der letzten Maschine (für die Optik)", "Répartiteur aussi devant la dernière machine (esthétique)"),
        ["tip.endSplitter"] = ("The last splitter of a manifold does nothing, but keeps every machine's input looking the same. Adds one splitter per manifold to the totals.", "Der letzte Splitter eines Verteilers bewirkt nichts, sieht aber einheitlich aus. Zählt einen Splitter pro Verteiler dazu.", "Le dernier répartiteur d'un collecteur ne sert à rien mais garde un aspect uniforme. Ajoute un répartiteur par collecteur."),
        ["summary.logistics"] = ("   ·   {0} splitters, {1} mergers, {2} pipe junctions", "   ·   {0} Splitter, {1} Zusammenführer, {2} Rohrverbindungen", "   ·   {0} répartiteurs, {1} fusionneurs, {2} jonctions"),
        ["grp.belts"] = ("Belts & splitters", "Bänder & Splitter", "Convoyeurs & répartiteurs"),
        ["lbl.belt"] = ("Belt", "Band", "Convoyeur"),
        ["lbl.pipe"] = ("Pipe", "Rohr", "Tuyau"),
        ["belt.auto"] = ("Auto — best unlocked at this tier", "Auto – bestes auf dieser Stufe freigeschaltetes", "Auto — le meilleur débloqué à ce palier"),
        ["belt.current"] = ("Planning with {0} belts and {1} pipes; bigger flows are split into parallel lines.", "Geplant mit {0}-Bändern und {1}-Rohren; größere Ströme werden auf parallele Linien aufgeteilt.", "Planifié avec convoyeurs {0} et tuyaux {1} ; les flux plus grands sont répartis sur des lignes parallèles."),
        ["col.line"] = ("Line", "Linie", "Ligne"),
        ["col.belt"] = ("Belt / pipe", "Band / Rohr", "Convoyeur / tuyau"),
        ["split.lines"] = ("Too much for one belt: {0} parallel lines, each fed by its own machines", "Zu viel für ein Band: {0} parallele Linien, jede mit eigenen Maschinen", "Trop pour un convoyeur : {0} lignes parallèles, chacune alimentée par ses propres machines"),
        ["edge.belts"] = ("×{0} {1}", "×{0} {1}", "×{0} {1}"),
        ["warn.notConverged"] = ("Drained mode: this plan is very large, so the splitter/supply balancing stopped early — add a little spare supply.", "Abgeführte Produkte: Der Plan ist sehr groß, der Splitter-/Zufuhrausgleich wurde früh beendet – etwas Reserve einplanen.", "Sorties drainées : plan très grand, l'équilibrage répartiteurs/apport s'est arrêté tôt — prévoyez un peu de marge."),
        ["warn.machineOverBelt"] = ("One {0} machine needs {1}/min — more than one {2} carries. Feed each with {3} belts merged at the machine, or pick a faster belt.", "Eine {0}-Maschine braucht {1}/min – mehr als ein {2} trägt. Jede mit {3} Bändern (an der Maschine zusammengeführt) versorgen oder schnelleres Band wählen.", "Une machine {0} demande {1}/min — plus qu'un {2} ne transporte. Alimentez-la avec {3} convoyeurs fusionnés à la machine, ou choisissez un convoyeur plus rapide."),
        ["node.line"] = ("line {0}/{1}", "Linie {0}/{1}", "ligne {0}/{1}"),
        ["node.inLines"] = ("in {0} lines", "in {0} Linien", "en {0} lignes"),
        ["btn.useSave"] = ("Use save", "Spielstand nutzen", "Utiliser la sauvegarde"),
        ["tip.useSave"] = ("On: plan only with recipes unlocked in the save. Off: ignore the save (keeps it loaded) and use this tab's tier and alternate/MAM settings — quick way to see what unlocking more would give you.", "An: nur mit im Spielstand freigeschalteten Rezepten planen. Aus: Spielstand ignorieren (bleibt geladen) und Stufe/Alternativen/MAM dieses Tabs verwenden – so siehst du schnell, was weitere Freischaltungen bringen.", "Activé : planifier uniquement avec les recettes débloquées dans la sauvegarde. Désactivé : ignorer la sauvegarde (elle reste chargée) et utiliser le palier et les réglages alternatives/M.A.M. de cet onglet — pour voir vite ce que d'autres déblocages apporteraient."),
        ["warn.notSettled"] = ("Drained mode: the splitter/supply balancing didn't fully settle for this plan — add a little spare supply.", "Abgeführte Produkte: Der Splitter-/Zufuhrausgleich hat sich bei diesem Plan nicht ganz eingependelt – etwas Reserve einplanen.", "Sorties drainées : l'équilibrage répartiteurs/apport ne s'est pas complètement stabilisé pour ce plan — prévoyez un peu de marge."),
        ["tab.guards"] = ("Clog guards", "Stauschutz", "Anti-blocage"),
        ["tab.guardsCount"] = ("Clog guards ({0})", "Stauschutz ({0})", "Anti-blocage ({0})"),
        ["tab.guardsWarn"] = ("⚠ Clog guards ({0} required)", "⚠ Stauschutz ({0} nötig)", "⚠ Anti-blocage ({0} requis)"),
        ["tab.guardsMixed"] = ("⚠ Clog guards ({0} required, {1} resolved)", "⚠ Stauschutz ({0} nötig, {1} gelöst)", "⚠ Anti-blocage ({0} requis, {1} résolus)"),
        ["tab.guardsResolved"] = ("✓ Clog guards (all {0} resolved)", "✓ Stauschutz (alle {0} gelöst)", "✓ Anti-blocage (les {0} résolus)"),
        ["guard.hint"] = ("Machines with several outputs stop completely when ANY output backs up. Every overflow needs somewhere that never fills: an AWESOME Sink or generators (a box fills up, and an output isn't guaranteed to be taken). What processing makes is an overflow too; it carries on in its own card below.", "Maschinen mit mehreren Ausgängen stehen still, sobald EIN Ausgang staut. Jeder Überlauf braucht ein Ziel, das nie voll wird: eine AWESOME-Senke oder Generatoren. Was die Verarbeitung macht, ist auch ein Überlauf; es geht in einer eigenen Karte darunter weiter.", "Les machines à plusieurs sorties s'arrêtent dès qu'UNE sortie bloque. Chaque débordement doit aller où rien ne se remplit : un Puits GÉNIAL ou des générateurs. Ce que produit le traitement est aussi un débordement ; il continue dans sa propre carte ci-dessous."),
        ["guard.col.machine"] = ("Machines", "Maschinen", "Machines"),
        ["guard.col.output"] = ("Output", "Ausgang", "Sortie"),
        ["guard.col.level"] = ("Need", "Bedarf", "Besoin"),
        ["guard.col.device"] = ("Guard", "Schutz", "Protection"),
        ["guard.col.where"] = ("Where / how", "Wo / wie", "Où / comment"),
        ["guard.required"] = ("Required", "Nötig", "Requis"),
        ["guard.recommended"] = ("Recommended", "Empfohlen", "Recommandé"),
        ["guard.smart"] = ("Smart splitter (Overflow)", "Intelligenter Splitter (Überlauf)", "Répartiteur intelligent (Débordement)"),
        ["guard.valve"] = ("Junction + valve", "Verbindungsstück + Ventil", "Jonction + vanne"),
        ["guard.smartHow"] = ("Right after the {0} output belt: {1} on a normal output, Overflow to your sink/storage (≈{2:0.##}/min spills).", "Direkt am Ausgangsband der {0}: {1} an einen normalen Ausgang, Überlauf zu deiner Senke/deinem Lager (≈{2:0.##}/min laufen über).", "Juste après le convoyeur de sortie des {0} : {1} sur une sortie normale, Débordement vers votre broyeur/stockage (≈{2:0.##}/min débordent)."),
        ["guard.valveHow"] = ("Right after the {0} output pipe: a junction; on the branch to {1} a valve set to {2:0.##} m³/min, the other branch to your sink/storage (≈{3:0.##} m³/min spills).", "Direkt am Ausgangsrohr der {0}: ein Verbindungsstück; im Zweig zu {1} ein Ventil auf {2:0.##} m³/min, der andere Zweig zu deiner Senke/deinem Lager (≈{3:0.##} m³/min laufen über).", "Juste après le tuyau de sortie des {0} : une jonction ; sur la branche vers {1} une vanne réglée à {2:0.##} m³/min, l'autre branche vers votre broyeur/stockage (≈{3:0.##} m³/min débordent)."),
        ["guard.recommendedWhy"] = ("Normally nothing spills — it protects the machines if {0} backs up.", "Normalerweise läuft nichts über – schützt die Maschinen, falls sich {0} staut.", "Normalement rien ne déborde — protège les machines si {0} se bloque."),
        ["guard.perLine"] = ("One per belt line ({0} lines).", "Eine pro Bandlinie ({0} Linien).", "Une par ligne ({0} lignes)."),
        ["guard.badge"] = ("overflow", "Überlauf", "débordement"),
        ["guard.badgeTip"] = ("Needs an overflow guard on: {0}. See the Clog guards tab.", "Braucht Stauschutz an: {0}. Siehe Tab Stauschutz.", "Protection anti-blocage requise sur : {0}. Voir l'onglet Anti-blocage."),
        ["warn.clog"] = ("{0} machine output(s) will clog without an overflow — see the Clog guards tab.", "{0} Maschinenausgang/-ausgänge staut sich ohne Überlauf – siehe Tab Stauschutz.", "{0} sortie(s) de machine va/vont se bloquer sans débordement — voir l'onglet Anti-blocage."),
        ["summary.valves"] = (", {0} valves", ", {0} Ventile", ", {0} vannes"),
        ["guard.routeAway"] = ("Route it all away", "Komplett wegleiten", "Tout évacuer"),
        ["guard.allAwayHow"] = ("Nothing in the plan uses it: send the whole {0} output straight to your sink/storage (≈{1:0.##} {2}). If it has nowhere to go, the machines stop.", "Nichts im Plan verwendet es: den gesamten Ausgang der {0} direkt zu deiner Senke/deinem Lager leiten (≈{1:0.##} {2}). Ohne Abfluss stoppen die Maschinen.", "Rien dans le plan ne l'utilise : envoyez toute la sortie des {0} vers votre broyeur/stockage (≈{1:0.##} {2}). Sans issue, les machines s'arrêtent."),
        ["tab.layout"] = ("Layout", "Layout", "Plan d'usine"),
        ["btn.exportPng"] = ("Export PNG…", "PNG exportieren…", "Exporter PNG…"),
        ["btn.exportCsv"] = ("Export CSV…", "CSV exportieren…", "Exporter CSV…"),
        ["btn.exportBp"] = ("Export blueprints…", "Blaupausen exportieren…", "Exporter les plans…"),
        ["tip.exportBp"] = ("Writes the layout as game blueprints (one per tile, \"<tab> r1c1\" …) into a folder you pick — normally your session's folder under SaveGames\\blueprints. Needs Node.js installed.", "Schreibt das Layout als Spiel-Blaupausen (eine pro Kachel, \"<Tab> r1c1\" …) in einen Ordner deiner Wahl — normalerweise den Ordner deines Spielstands unter SaveGames\\blueprints. Benötigt Node.js.", "Écrit le plan en plans de jeu (un par tuile, « <onglet> r1c1 »…) dans le dossier choisi — normalement celui de ta partie sous SaveGames\\blueprints. Nécessite Node.js."),
        ["bp.needTile"] = ("Pick a blueprint size (Mk2 / Mk3) first: blueprints are written per tile.", "Wähle zuerst eine Blaupausengröße (Mk2 / Mk3): Blaupausen werden pro Kachel geschrieben.", "Choisis d'abord une taille de plan (Mk2 / Mk3) : les plans sont écrits par tuile."),
        ["bp.noNode"] = ("Writing blueprints needs Node.js, and it wasn't found.\n\nOpen nodejs.org to download it? (Restart this app after installing.)", "Zum Schreiben von Blaupausen wird Node.js benötigt, es wurde nicht gefunden.\n\nnodejs.org zum Herunterladen öffnen? (Danach diese App neu starten.)", "L'écriture des plans nécessite Node.js, introuvable.\n\nOuvrir nodejs.org pour le télécharger ? (Redémarre l'application après l'installation.)"),
        ["bp.noWriter"] = ("The blueprint writer wasn't found: {0}", "Der Blaupausen-Schreiber wurde nicht gefunden: {0}", "Le générateur de plans est introuvable : {0}"),
        ["bp.pickFolder"] = ("Pick the blueprint folder (your session's folder under SaveGames\\blueprints)", "Blaupausen-Ordner wählen (Ordner deines Spielstands unter SaveGames\\blueprints)", "Choisis le dossier des plans (celui de ta partie sous SaveGames\\blueprints)"),
        ["bp.noBase"] = ("There's no blueprint made in game in \"{0}\".\n\nBlueprints need your session's details: save any blueprint in game into this folder first, then export.", "In \"{0}\" liegt keine im Spiel erstellte Blaupause.\n\nBlaupausen brauchen die Daten deines Spielstands: speichere zuerst im Spiel irgendeine Blaupause in diesen Ordner.", "Aucun plan créé en jeu dans « {0} ».\n\nLes plans ont besoin des infos de ta partie : enregistre d'abord n'importe quel plan en jeu dans ce dossier."),
        ["bp.writing"] = ("Writing blueprints…", "Blaupausen werden geschrieben…", "Écriture des plans…"),
        ["bp.checkNode"] = ("Checking for Node.js…", "Node.js wird gesucht…", "Recherche de Node.js…"),
        ["bp.installing"] = ("First export: installing the blueprint writer (npm)…", "Erster Export: Blaupausen-Schreiber wird installiert (npm)…", "Premier export : installation du générateur de plans (npm)…"),
        ["bp.installFailed"] = ("The blueprint writer couldn't be installed (it needs npm and the network): {0}\nThe \"full\" build of the app has everything built in and needs neither.", "Der Blaupausen-Schreiber konnte nicht installiert werden (braucht npm und Netzwerk): {0}\nDie „Voll“-Version der App enthält alles und braucht beides nicht.", "Impossible d'installer le générateur de plans (npm et réseau requis) : {0}\nLa version « complète » de l'application contient tout et n'en a pas besoin."),
        ["bp.progress"] = ("{0} / {1} blueprints written", "{0} / {1} Blaupausen geschrieben", "{0} / {1} plans écrits"),
        ["bp.done"] = ("{0} blueprints written to {1}", "{0} Blaupausen nach {1} geschrieben", "{0} plans écrits dans {1}"),
        ["bp.summary"] = ("{0} blueprints written to:\n{1}\n\n{2} belts / pipes between tiles need joining by hand — see \"wiring.txt\".\n(Session details taken from {3})", "{0} Blaupausen geschrieben nach:\n{1}\n\n{2} Bänder / Rohre zwischen Kacheln von Hand verbinden — siehe \"wiring.txt\".\n(Spielstanddaten aus {3})", "{0} plans écrits dans :\n{1}\n\n{2} tapis / tuyaux entre tuiles à relier à la main — voir « wiring.txt ».\n(Infos de partie prises de {3})"),
        ["bp.wiringHead"] = ("{0}: belts / pipes to join by hand between tiles (east, north from the south-west corner)", "{0}: Bänder / Rohre zwischen Kacheln von Hand verbinden (Ost, Nord ab der Südwestecke)", "{0} : tapis / tuyaux à relier à la main entre tuiles (est, nord depuis le coin sud-ouest)"),
