        ["lbl.blueprint"] = ("Blueprint", "Blaupause", "Plan"),
        ["status.floor"] = ("Floor {0} of {1}: placing machines and routing belts", "Etage {0} von {1}: Maschinen platzieren, Bänder verlegen", "Étage {0} sur {1} : placement et câblage"),
