        ["kpi.clogNoneSub"] = ("no multi-output machine can back up", "keine Maschine mit mehreren Ausgängen staut", "aucune machine à sorties multiples ne bloque"),
        ["hdr.overflow"] = ("Overflow processing", "Überlaufverarbeitung", "Traitement des débordements"),
        ["clog.status.good"] = ("✓ Safe", "✓ Sicher", "✓ Sûr"),
        ["clog.status.next"] = ("→ continues below", "→ geht unten weiter", "→ suite ci-dessous"),
        ["clog.status.warn"] = ("⚠ Will clog when full", "⚠ Staut, wenn voll", "⚠ Bloquera une fois plein"),
        ["clog.status.info"] = ("Recommended", "Empfohlen", "Recommandé"),
        ["hint.overflowRow"] = ("Processes an overflow: change it in Clog guards (how to process).", "Verarbeitet einen Überlauf: nur unter Stauschutz änderbar (Verarbeitung).", "Traite un débordement : à modifier dans Anti-blocage (traitement)."),
        ["tip.clogHow"] = ("What happens to the surplus. Only an AWESOME Sink or generators never fill up (a box fills, and an output isn't guaranteed to be taken). More machines can turn it into something else, but that product is an overflow too and gets its own row to deal with; one of this plan's products can merge into its output through a smart splitter with a sink on Overflow.", "Was mit dem Überschuss passiert: Überlauf in eine Kiste (jemand muss sie leeren), Überlauf in eine AWESOME-Senke, oder ein paar Maschinen mehr machen etwas anderes daraus (das Produkt geht zur Ausgabe dieses Gegenstands). Mit den letzten beiden läuft die Fabrik unbegrenzt allein.", "Ce que devient le surplus : débordement dans une caisse (à vider), débordement dans un Puits GÉNIAL, ou quelques machines de plus en font autre chose (le produit rejoint la sortie de cet objet). Les deux derniers laissent l'usine tourner seule indéfiniment."),
        ["clog.box"] = ("Overflow into a box (fills up — not safe)", "Überlauf in eine Kiste (wird voll — nicht sicher)", "Débordement dans une caisse (se remplit — pas sûr)"),
        ["clog.keep"] = ("Keep as is (machines use all of it)", "So lassen (Maschinen verbrauchen alles)", "Laisser tel quel (les machines utilisent tout)"),
        ["clog.gen"] = ("Burn in {0} ({1:0.#}/min each, {2:0} MW)", "In {0} verbrennen ({1:0.#}/min je, {2:0} MW)", "Brûler dans {0} ({1:0.#}/min chacun, {2:0} MW)"),
        ["clog.merge"] = ("Merge into the {0} output (smart splitter, Overflow to an AWESOME Sink)", "In die {0}-Ausgabe einspeisen (intelligenter Teiler, Überlauf in eine AWESOME-Senke)", "Fusionner dans la sortie {0} (répartiteur intelligent, débordement vers un Puits GÉNIAL)"),
        ["clog.chain"] = ("{2:0.##} {3} {0}: made from the surplus by {1} — it's an overflow too and needs its own way out.", "{2:0.##} {3} {0}: von {1} aus dem Überschuss gemacht — auch ein Überlauf, braucht einen eigenen Ausweg.", "{2:0.##} {3} {0} : fait du surplus par {1} — c'est aussi un débordement, il lui faut sa propre sortie."),
        ["clog.boxHow"] = ("Now it overflows into a box: once full, it backs up and the whole chain stops.", "Jetzt Überlauf in eine Kiste: ist sie voll, staut es und die ganze Kette steht.", "Pour l'instant dans une caisse : une fois pleine, tout se bloque."),
        ["clog.genHow"] = ("The overflow is burnt in generators (they never fill up).", "Der Überlauf wird in Generatoren verbrannt (die werden nie voll).", "Le débordement est brûlé dans des générateurs (ils ne se remplissent jamais)."),
        ["clog.mergeHow"] = ("Through a smart splitter first: one output merges into that product's output, Overflow goes to an AWESOME Sink — a full output can't back it up.", "Erst durch einen intelligenten Teiler: ein Ausgang in die Ausgabe des Produkts, Überlauf in eine AWESOME-Senke — eine volle Ausgabe staut nichts.", "D'abord un répartiteur intelligent : une sortie rejoint la sortie du produit, le débordement va dans un Puits GÉNIAL — une sortie pleine ne bloque rien."),
        ["item.overflow"] = ("{0} (overflow)", "{0} (Überlauf)", "{0} (débordement)"),
        ["clog.sink"] = ("Overflow into an AWESOME Sink", "Überlauf in eine AWESOME-Senke", "Débordement dans un Puits GÉNIAL"),
        ["clog.recipe"] = ("→ {0} ({1} → {2})", "→ {0} ({1} → {2})", "→ {0} ({1} → {2})"),
        ["clog.sinkHow"] = ("The overflow goes straight into an AWESOME Sink (smart splitter Overflow).", "Der Überlauf geht direkt in eine AWESOME-Senke (intelligenter Teiler, Überlauf).", "Le débordement va directement dans un Puits GÉNIAL (répartiteur intelligent, débordement)."),
        ["clog.recipeHow"] = ("The surplus is used up by {0}; what it makes is a new overflow (the card below).", "Der Überschuss wird von {0} verbraucht; was dabei entsteht, ist ein neuer Überlauf (Karte darunter).", "Le surplus est utilisé par {0} ; ce qu'il produit est un nouveau débordement (carte ci-dessous)."),
        ["out.sink"] = ("Surplus (overflow into an AWESOME Sink)", "Überschuss (Überlauf in eine AWESOME-Senke)", "Surplus (débordement dans un Puits GÉNIAL)"),
        ["loop.title"] = ("Plastic + rubber: recycling loop?", "Kunststoff + Gummi: Recycling-Schleife?", "Plastique + caoutchouc : boucle de recyclage ?"),
        ["loop.ask"] = ("This plan makes only plastic and rubber, and your recipes allow the recycling loop:\n\nCrude oil → Heavy Oil Residue (alt) → Diluted Packaged Fuel (alt, with packaged water) → unpackaged fuel → Recycled Plastic / Recycled Rubber, turning each into the other. About 80 plastic + rubber per 30 crude oil (about 40 with the plain recipes).\n\nIt needs a one-off starting stock: some plastic and rubber in the recycling refineries and some empty canisters in the packagers. Smart splitters feed the loop first and only send the surplus to the output, so the loop never runs dry.\n\nYes: use the recycling loop.\nNo: use the plain recipes (simpler, less per crude oil).",
            "Dieser Plan stellt nur Kunststoff und Gummi her, und deine Rezepte erlauben die Recycling-Schleife:\n\nRohöl → Schweröl-Rückstand (Alt.) → Verdünnter verpackter Treibstoff (Alt., mit verpacktem Wasser) → entpackter Treibstoff → Recycelter Kunststoff / Recycelter Gummi, die sich gegenseitig herstellen. Etwa 80 Kunststoff + Gummi pro 30 Rohöl (etwa 40 mit den normalen Rezepten).\n\nSie braucht einmalig einen Startbestand: etwas Kunststoff und Gummi in den Recycling-Raffinerien und leere Kanister in den Verpackern. Intelligente Teiler versorgen zuerst die Schleife und schicken nur den Überschuss zur Ausgabe, so läuft sie nie leer.\n\nJa: Recycling-Schleife verwenden.\nNein: normale Rezepte (einfacher, weniger pro Rohöl).",
            "Ce plan ne produit que du plastique et du caoutchouc, et vos recettes permettent la boucle de recyclage :\n\nPétrole brut → Résidu de pétrole lourd (alt.) → Carburant conditionné dilué (alt., avec de l'eau conditionnée) → carburant déconditionné → Plastique recyclé / Caoutchouc recyclé, chacun produisant l'autre. Environ 80 plastique + caoutchouc pour 30 pétrole brut (environ 40 avec les recettes normales).\n\nIl faut un stock de départ unique : un peu de plastique et de caoutchouc dans les raffineries de recyclage et des bidons vides dans les conditionneurs. Des répartiteurs intelligents servent la boucle d'abord et n'envoient que le surplus à la sortie : la boucle ne s'arrête jamais.\n\nOui : utiliser la boucle de recyclage.\nNon : recettes normales (plus simple, moins par pétrole brut)."),
        ["loop.seed"] = ("Recycling loop: before starting, put some plastic and rubber in the recycling refineries and empty canisters in the packagers; the loop keeps them topped up after that.", "Recycling-Schleife: vor dem Start etwas Kunststoff und Gummi in die Recycling-Raffinerien und leere Kanister in die Verpacker legen; danach füllt die Schleife sie selbst nach.", "Boucle de recyclage : avant de démarrer, mettez du plastique et du caoutchouc dans les raffineries de recyclage et des bidons vides dans les conditionneurs ; la boucle les réapprovisionne ensuite."),
        ["lbl.timeLimit"] = ("Time limit for the layout", "Zeitlimit für das Layout", "Temps limite pour la disposition"),
        ["tip.timeLimit"] = ("More time gives big plans a better chance of a routed layout. With a short limit, large plans (many machine types, several floors) will likely run out of time and get the row layout instead.", "Mehr Zeit gibt großen Plänen eine bessere Chance auf ein verlegtes Layout. Bei kurzem Limit reicht die Zeit für große Pläne (viele Maschinentypen, mehrere Etagen) wahrscheinlich nicht, und sie bekommen das Reihen-Layout.", "Plus de temps donne aux grands plans une meilleure chance d'obtenir une disposition câblée. Avec une limite courte, les grands plans (beaucoup de types de machines, plusieurs étages) manqueront probablement de temps et recevront la disposition en rangées."),
        ["layout.left"] = ("{0} left (limit {1})", "noch {0} (Limit {1})", "{0} restant (limite {1})"),
        ["layout.overtime"] = ("Time's up, finishing…", "Zeit abgelaufen, wird abgeschlossen…", "Temps écoulé, finalisation…"),
        ["layout.fallback"] = ("If no routed layout is found in time, you get the simple row layout instead (machines in rows, longer belts, more space). To try again with more time, raise the limit under ⚙ Advanced and press “Lay out again”.", "Wird rechtzeitig kein verlegtes Layout gefunden, gibt es stattdessen das einfache Reihen-Layout (Maschinen in Reihen, längere Bänder, mehr Platz). Für einen neuen Versuch das Limit unter ⚙ Erweitert erhöhen und „Neu anordnen“ klicken.", "Si aucune disposition câblée n'est trouvée à temps, vous obtenez la disposition simple en rangées (machines en rangées, convoyeurs plus longs, plus de place). Pour réessayer, augmentez la limite dans ⚙ Avancé et cliquez sur « Recalculer »."),
        ["status.stack"] = ("Stacking {0} congested corridor(s)", "{0} enge Korridore stapeln", "Empilement de {0} couloir(s) encombré(s)"),
        ["status.twostage"] = ("Retrying: short lines first, long lines on upper levels", "Neuer Versuch: kurze Linien zuerst, lange oben", "Nouvel essai : lignes courtes d'abord, longues en hauteur"),
        ["status.compact"] = ("Compacting (closing up empty space)", "Verdichten (Lücken schließen)", "Compactage (réduction des vides)"),
        ["status.narrow"] = ("Trying tighter machine groups", "Versuche engere Maschinengruppen", "Essai de groupes de machines plus serrés"),
        ["chk.backUp"] = ("Intermediates may back up (no overproduction when there are no byproducts)", "Zwischenprodukte dürfen sich stauen (keine Überproduktion ohne Nebenprodukte)", "Les produits intermédiaires peuvent s'accumuler (pas de surproduction sans sous-produits)"),
        ["tip.backUp"] = ("An intermediate used only by machines may back up on its belt: its splitters then balance by themselves, so no extra supply is planned. Not for items whose makers have a byproduct — a backed-up byproduct stops the machine and production drops.", "Ein Zwischenprodukt, das nur Maschinen nutzen, darf sich auf dem Band stauen: die Splitter gleichen dann selbst aus, keine Extrazufuhr. Nicht, wenn seine Hersteller ein Nebenprodukt haben — ein gestautes Nebenprodukt stoppt die Maschine.", "Un produit intermédiaire utilisé seulement par des machines peut s'accumuler : les répartiteurs s'équilibrent seuls, aucun apport supplémentaire. Pas si ses producteurs ont un sous-produit — un sous-produit bloqué arrête la machine."),
        ["status.steps"] = ("Trying floors split by production step", "Versuche Etagen nach Produktionsschritt", "Essai d'étages par étape de production"),
        ["status.rows"] = ("Falling back to the row layout", "Weiche auf das Reihen-Layout aus", "Repli sur la disposition en rangées"),
        ["status.elapsed"] = ("{0} s so far", "bisher {0} s", "{0} s écoulées"),
        ["layout.handTag"] = ("place by hand", "von Hand", "à la main"),
        ["bp.off"] = ("No tiles", "Keine Kacheln", "Sans tuiles"),
        ["bp.mk2"] = ("Mk2 (5×5)", "Mk2 (5×5)", "Mk2 (5×5)"),
        ["bp.mk3"] = ("Mk3 (6×6)", "Mk3 (6×6)", "Mk3 (6×6)"),
        ["chk.bigTank"] = ("Industrial fluid buffers", "Industrielle Flüssigkeitspuffer", "Tampons de fluide industriels"),
        ["tip.bigTank"] = ("Fluid input / output boxes use the Industrial Fluid Buffer (2400 m³, about 12 m across) instead of the Fluid Buffer (400 m³, 4 m). Layouts get bigger (plastic: 4 -> 7 blueprints when measured).", "Flüssigkeits-Ein-/Ausgänge nutzen den industriellen Flüssigkeitspuffer (2400 m³, ca. 12 m breit) statt des Flüssigkeitspuffers (400 m³, 4 m). Layouts werden größer (Kunststoff: gemessen 4 -> 7 Blaupausen).", "Les entrées / sorties de fluide utilisent le tampon de fluide industriel (2400 m³, environ 12 m) au lieu du tampon de fluide (400 m³, 4 m). Les plans grandissent (plastique : 4 -> 7 plans mesurés)."),
        ["cache.bigTank"] = ("industrial buffers", "industrielle Puffer", "tampons industriels"),
        ["hand.warn"] = ("Machines may cross tiles: blueprints may come out misplaced or clipped.\n\n• Machines across a tile border aren't in the blueprints: you place them by hand (✋ marks).\n• No safety zones by the tile borders: belts / pipes, splitters, mergers and ramps near a border may be cut off, sit off their ports or need finishing by hand (see \"join by hand\" in wiring.txt).\n• A splitter / merger may sit too close to a bend, its output twisted.\n\nIt usually saves blueprints, at the cost of more fixing by hand. Continue?", "Maschinen dürfen Kacheln überqueren: Blaupausen können verrutscht oder abgeschnitten sein.\n\n• Maschinen über einer Kachelgrenze fehlen in den Blaupausen: du baust sie von Hand (✋).\n• Keine Schutzzonen an den Grenzen: Bänder / Rohre, Splitter, Merger und Rampen nahe einer Grenze können abgeschnitten sein, neben ihren Anschlüssen sitzen oder Handarbeit brauchen (siehe \"von Hand verbinden\" in wiring.txt).\n• Ein Splitter / Merger kann zu nah an einer Kurve sitzen, sein Ausgang verdreht.\n\nSpart meist Blaupausen, kostet aber mehr Handarbeit. Fortfahren?", "Machines à cheval sur les tuiles : les plans peuvent être décalés ou tronqués.\n\n• Les machines à cheval sur une limite ne sont pas dans les plans : tu les places à la main (✋).\n• Pas de zones de sécurité aux limites : tapis / tuyaux, répartiteurs, fusionneurs et rampes près d'une limite peuvent être coupés, décalés de leurs ports ou à terminer à la main (voir « à relier à la main » dans wiring.txt).\n• Un répartiteur / fusionneur peut être trop près d'un virage, sa sortie tordue.\n\nÉconomise souvent des plans, mais demande plus de retouches. Continuer ?"),
        ["chk.byHand"] = ("Machines may cross tiles (place by hand)", "Maschinen dürfen Kacheln überqueren (von Hand platzieren)", "Machines à cheval sur les tuiles (placées à la main)"),
        ["tip.byHand"] = ("Machines may straddle a blueprint border: they're left out of the blueprints and you place them yourself. While one machine of a group sits inside a blueprint, the others line up from it; if every machine of a group is placed by hand, the group's corner sits on a foundation corner. ⚠ Belts / pipes near tile borders may be clipped or misplaced and need fixing by hand.", "Maschinen dürfen über eine Blaupausengrenze ragen: sie fehlen in den Blaupausen und werden von Hand gebaut. Steht eine Maschine der Gruppe in einer Blaupause, richten sich die anderen an ihr aus; muss die ganze Gruppe von Hand gebaut werden, liegt ihre Ecke auf einer Fundamentecke. ⚠ Bänder / Rohre nahe Kachelgrenzen können abgeschnitten oder verrutscht sein.", "Les machines peuvent chevaucher une limite de plan : elles sont retirées des plans et placées à la main. Si une machine du groupe est dans un plan, les autres s'alignent sur elle ; si tout le groupe est placé à la main, son coin est sur un coin de fondation. ⚠ Tapis / tuyaux près des limites peuvent être tronqués ou décalés."),
        ["layout.byHand"] = ("{0} machines placed by hand", "{0} Maschinen von Hand", "{0} machines placées à la main"),
        ["lbl.cached"] = ("Saved", "Gespeichert", "Enregistrés"),
        ["tip.cached"] = ("Layouts this tab has worked out, each with its plan (↩ = another plan). Pick one to bring back its plan and layout options — no recalculation.", "Von diesem Tab berechnete Layouts, jeweils mit ihrem Plan (↩ = anderer Plan). Eines wählen, um Plan und Layout-Optionen wiederherzustellen – ohne Neuberechnung.", "Plans calculés par cet onglet, chacun avec son plan de production (↩ = autre plan). En choisir un pour rétablir ce plan et ses options — sans recalcul."),
        ["btn.relayout"] = ("Lay out again", "Neu anordnen", "Recalculer"),
        ["tip.relayout"] = ("Ignore the saved layout and work it out again (replacing it).", "Gespeichertes Layout ignorieren und neu berechnen (ersetzt es).", "Ignorer le plan enregistré et le recalculer (il est remplacé)."),
        ["layout.fromCache"] = ("saved layout", "gespeichertes Layout", "plan enregistré"),
